package com.example.shortener.feature.link.controller;
import com.example.shortener.feature.link.service.ShortLinkService; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*;
@Controller public class RedirectController {private final ShortLinkService s; public RedirectController(ShortLinkService s){this.s=s;} @GetMapping("/r/{code}") public ResponseEntity<Void> redirect(@PathVariable String code,HttpServletRequest req){String ip=req.getHeader("X-Forwarded-For");if(ip!=null)ip=ip.split(",")[0].trim();if(ip==null)ip=req.getRemoteAddr();String target=s.resolveAndTrack(code,ip,req.getHeader("User-Agent"));return ResponseEntity.status(HttpStatus.FOUND).header(HttpHeaders.LOCATION,target).build();}}
